class HallucinationDetector(Estimator):
    def __init__(self, context: Dict[str, Any]) -> None:
        super().__init__(
            context,
            stats_dependencies=[
                "sequence_logprobs",
            ],
            level="sequence",
        )

    def __call__(self, stats: Dict[str, np.ndarray]) -> np.ndarray:
        """
        Detects hallucinations by computing the mean negative log-probability per sequence.
        Hypothesis: Normalizing NLL by sequence length isolates the model's average confidence 
        per token, preventing long sequences from artificially inflating scores and short sequences 
        from masking errors due to summation.
        """
        scores = []
        for seq_logprobs in stats["sequence_logprobs"]:
            # seq_logprobs shape: (n_i - 1,)
            if len(seq_logprobs) == 0:
                scores.append(0.0)
            else:
                # Use mean to normalize for sequence length
                score = -np.mean(seq_logprobs)
                scores.append(score)

        return np.array(scores, dtype=np.float32)

class HallucinationDetector(Estimator):
    def __init__(self, context: Dict[str, Any]) -> None:
        super().__init__(
            context,
            stats_dependencies=[
                "sequence_logprobs",
            ],
            level="sequence",
        )

    def __call__(self, stats: Dict[str, np.ndarray]) -> np.ndarray:
        """
        Detects hallucinations by summing negative log-probabilities of tokens 
        that fall below the sequence-specific median log-probability.

        Hypothesis: Hallucinated tokens are relative outliers within their own sequence; 
        using a dynamic median threshold normalizes for sequence-level confidence variance, 
        isolating tokens that are improbably low compared to the model's own expectation for that context.
        """
        seq_logprobs = stats["sequence_logprobs"]
        scores = []

        for seq in seq_logprobs:
            if len(seq) == 0:
                scores.append(0.0)
                continue

            # Dynamic threshold: Median of the current sequence's log-probs
            median_val = np.median(seq)

            # Identify tokens more surprising than the median
            extreme_mask = seq < median_val

            # Sum the negative log-probs of these relative outliers
            score = -np.sum(seq[extreme_mask])
            scores.append(score)

        return np.array(scores, dtype=np.float32)

